def compute(vars):
    value_2018 = vars["v1"]
    value_2017 = vars["v2"]
    difference = value_2018 - value_2017

    return {
        "value": difference,
        "trace": {
            "value_2018": value_2018,
            "value_2017": value_2017,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
